import { AxiosRequestConfig, AxiosResponse } from 'axios';

/**
 * Options for initializing the FluentRestClient.
 */
export interface ClientOptions {
  /** Callback to get the current access token. */
  onGetToken?: () => Promise<string | null>;
  /** Callback to save a new access token. */
  onSaveToken?: (token: string) => Promise<void>;
  /** Callback to perform the token refresh API call. */
  onRefreshToken?: () => Promise<string>;
  /** Callback for general authentication errors (e.g., redirect to login). */
  onAuthError?: (error: any) => void;
  /** Number of retries for 5xx or network errors. */
  retries?: number;
  /** Initial delay for exponential backoff (ms). */
  retryDelay?: number;
  /** Allowed HTTP methods for automatic retries. Defaults to ['get', 'head', 'options', 'put', 'delete']. */
  retryMethods?: string[];
  /** Custom logger function for retry messages or debug events. */
  logger?: ((message: string) => void) | null;
  /** Additional Axios client configuration options. */
  axiosConfig?: AxiosRequestConfig;
}

export interface SafeResult<T = any> {
  data: T | null;
  status: number;
  ok: boolean;
  error: any | null;
  headers: Record<string, any> | null;
}

export interface UploadProgressEvent {
  loaded: number;
  total: number;
  percent: number;
  event: any;
}

export interface CacheOptions {
  ttl?: number;
  key?: string;
}

export interface PaginateOptions<T = any> {
  limit?: number;
  pageParam?: string;
  limitParam?: string;
  startPage?: number;
  extractItems?: (response: any) => T[];
}

export interface PageResult<T = any> {
  page: number;
  items: T[];
  rawResponse: any;
}

/**
 * Fluent builder for REST resources.
 */
export class Resource<IsSafe extends boolean = false> {
  constructor(httpClient: any, name: string, options?: any);

  /** Enables safe mode: returns { data, status, ok, error, headers } instead of throwing. */
  safe(): Resource<true>;
  id(val: string | number): Resource<IsSafe>;
  sub(path: string): Resource<IsSafe>;
  query(params: Record<string, any>): Resource<IsSafe>;
  headers(headers: Record<string, string>): Resource<IsSafe>;
  timeout(ms: number): Resource<IsSafe>;
  signal(abortSignal: AbortSignal): Resource<IsSafe>;
  onProgress(fn: (progress: UploadProgressEvent) => void): Resource<IsSafe>;
  cache(options?: number | CacheOptions): Resource<IsSafe>;

  get<T = any>(): Promise<IsSafe extends true ? SafeResult<T> : AxiosResponse<T>>;
  post<T = any>(data?: any): Promise<IsSafe extends true ? SafeResult<T> : AxiosResponse<T>>;
  put<T = any>(data?: any): Promise<IsSafe extends true ? SafeResult<T> : AxiosResponse<T>>;
  patch<T = any>(data?: any): Promise<IsSafe extends true ? SafeResult<T> : AxiosResponse<T>>;
  delete<T = any>(): Promise<IsSafe extends true ? SafeResult<T> : AxiosResponse<T>>;

  upload<T = any>(data: any, method?: string): Promise<IsSafe extends true ? SafeResult<T> : AxiosResponse<T>>;
  paginate<T = any>(options?: PaginateOptions<T>): AsyncIterableIterator<PageResult<T>>;
}

/**
 * Main Fluent REST Client.
 */
export class FluentRestClient {
  constructor(baseUrl: string, options?: ClientOptions);
  
  /** Registers a global middleware. */
  use(middleware: { request?: (config: any) => any; response?: (response: any) => any }): FluentRestClient;
  
  /** Listens to outgoing request events. */
  onRequest(fn: (config: any) => void): FluentRestClient;

  /** Listens to successful response events. */
  onResponse(fn: (response: any) => void): FluentRestClient;

  /** Listens to request/server error events (useful for telemetry like Sentry). */
  onError(fn: (error: any, config: any) => void): FluentRestClient;

  /** Clears the in-memory response cache. */
  clearCache(): FluentRestClient;

  /** Starts a fluent builder for the specified resource. */
  resource(name: string): Resource<false>;
  
  /** Manually triggers a token refresh. */
  refreshToken(): Promise<string>;
}

export default FluentRestClient;


